            )

        weights = self._weights
        bias = self._bias
        out = _zeros((n_, o_ch, oh_, ow_))
        for n in range(n_):
            for o in range(o_ch):
                for oh in range(oh_):
                    for ow in range(ow_):
                        acc = bias[o]
                        for c in range(c_):
                            x_c = x[n][c]
                            w_c_o = weights[c][o]
