                                if ih < 0 or ih >= h_:
                                    continue
                                x_row = x_c[ih]
                                w_row = w_c_o[kh]
                                for kw in range(kw_):
                                    t_w = ow + p_ - kw
                                    if t_w % s_ != 0:
                                        continue
                                    iw = t_w // s_
                                    if 0 <= iw < w_:
                                        acc += x_row[iw] * w_row[kw]
                        if not math.isfinite(acc):
                            raise ValueError(
                                "forward 结果含有非有限值（NaN/inf）"
                            )
                        out[n][o][oh][ow] = acc

        self._x = x
        self._x_shape = (n_, c_, h_, w_)
        self._out_shape = (n_, o_ch, oh_, ow_)
        return out

