        dy_shape = _shape_of(dy, 4, "dy")
        if dy_shape != self._out_shape:
            raise ValueError(
                "dy 形状 %s 与最近输出形状 %s 不符"
                % (dy_shape, self._out_shape)
            )

        x = self._x
        weights = self._weights
        n_, c_, h_, w_ = self._x_shape
        _, o_ch, kh_, kw_ = self._w_shape
        oh_, ow_ = self._out_shape[2], self._out_shape[3]
        s_ = self._stride
        p_ = self._padding

        dx = _zeros((n_, c_, h_, w_))
        dw = _zeros((c_, o_ch, kh_, kw_))
        db = _zeros((o_ch,))

        # dx：n→o→kh→kw→oh→ow→(c) 累加。
        for n in range(n_):
            for o in range(o_ch):
                for kh in range(kh_):
                    for kw in range(kw_):
                        for oh in range(oh_):
                            t_h = oh + p_ - kh
                            if t_h % s_ != 0:
                                continue
                            ih = t_h // s_
                            if ih < 0 or ih >= h_:
                                continue
                            for ow in range(ow_):
                                t_w = ow + p_ - kw
                                if t_w % s_ != 0:
                                    continue
                                iw = t_w // s_
                                if iw < 0 or iw >= w_:
                                    continue
                                g = dy[n][o][oh][ow]
                                for c in range(c_):
                                    dx[n][c][ih][iw] += (
                                        g * weights[c][o][kh][kw]
                                    )

        # dweights：n→ih→iw→o→kh→kw→(c) 累加，oh/ow 由输入坐标反解。
        for n in range(n_):
            for ih in range(h_):
                for iw in range(w_):
                    for o in range(o_ch):
                        for kh in range(kh_):
                            oh = ih * s_ - p_ + kh
                            if oh < 0 or oh >= oh_:
                                continue
                            for kw in range(kw_):
                                ow = iw * s_ - p_ + kw
                                if ow < 0 or ow >= ow_:
                                    continue
                                g = dy[n][o][oh][ow]
                                for c in range(c_):
                                    dw[c][o][kh][kw] += (
                                        g * x[n][c][ih][iw]
                                    )

        # dbias：n→oh→ow→o 累加。
        for n in range(n_):
            for oh in range(oh_):
                for ow in range(ow_):
                    for o in range(o_ch):
                        db[o] += dy[n][o][oh][ow]

        for c in range(c_):
            for o in range(o_ch):
                for kh in range(kh_):
                    for kw in range(kw_):
                        if not math.isfinite(dw[c][o][kh][kw]):
                            raise ValueError(
                                "backward 的 dweights 含有非有限值"
                            )
        for n in range(n_):
            for c in range(c_):
                for ih in range(h_):
                    for iw in range(w_):
                        if not math.isfinite(dx[n][c][ih][iw]):
                            raise ValueError(
                                "backward 的 dx 含有非有限值"
                            )
        for o in range(o_ch):
            if not math.isfinite(db[o]):
                raise ValueError("backward 的 dbias 含有非有限值")

        return dx, dw, db


